def pedHead (st : PedSignalState) : Device :=
  { Build.device 101 .pedestrianSignal [20] (some (m 11, m (-10))) with
      pedState := some st, countdown := some false, inoperative := some false }

def pedestrian (pos : Vec) (moving headingKnown : Bool) : RoadUser :=
  let u := Build.user 1 [.pedestrian] pos Build.south
    (if moving then Units.metresPerSecond 1 else Units.metresPerSecond 0) (cm 30, cm 30, cm 90)
  if headingKnown then u else Build.withKin u (fun k => { k with heading := none })

/-- A scene generator: the pedestrian at `before` for k ≤ 1 and at `after` from k = 2. -/
def sceneGen (governs : List RegionId) (shows : List SignalIndication) (ped : PedSignalState)
    (before after : Vec) (headingKnown : Bool := true) : Nat → Timestamp → Scene :=
  fun k t =>
    Build.scene t (some 1)
      [ pedestrian (if k ≤ 1 then before else after) (k == 1) headingKnown ]
      structures
      [ head governs shows, pedHead ped ]

